#!/bin/sh
# 目标文件结构：段布局、符号表与重定位表
# 期望输出见 expected_output（本机 MinGW 工具链 + GNU Make 真实执行捕获）

cat > obj.c << 'EOF'
#include <stdio.h>

int g_inited = 42;              /* 已初始化 -> .data */
int g_zero;                     /* 未初始化 -> .bss */
static const char msg[] = "hi"; /* 只读 -> .rdata/.rodata */

static int helper(int x)        /* static -> 内部链接（小写 t） */
{
    return x + 1;
}

int exported(int x)             /* 外部链接（大写 T） */
{
    printf("%s\n", msg);
    return helper(x) + g_inited + g_zero;
}
EOF

cat > main.c << 'EOF'
#include <stdio.h>

int exported(int);

int main(void)
{
    printf("exported(1) = %d\n", exported(1));
    return 0;
}
EOF

gcc -c obj.c -o obj.o
objdump -h obj.o              # 段表：.text/.data/.bss/.rdata
size obj.o                    # text/data/bss 三段字节数
nm obj.o                      # T=外部定义 t=static B=bss D=data U=未定义
gcc -c main.c -o main.o
nm main.o                     # 注意 U exported：本单元欠账
gcc main.o obj.o -o app.exe
./app
